import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int t = Integer.parseInt(st.nextToken());
        StringBuilder out = new StringBuilder();
        while (t-- > 0) {
            String s = st.nextToken();
            StringBuilder e = new StringBuilder(), o = new StringBuilder();
            // Same-parity digits keep their order; merge the two subsequences greedily.
            for (char c : s.toCharArray()) ((c - '0') % 2 == 1 ? o : e).append(c);
            int i = 0, j = 0;
            while (i < e.length() && j < o.length()) out.append(e.charAt(i) < o.charAt(j) ? e.charAt(i++) : o.charAt(j++));
            out.append(e, i, e.length()).append(o, j, o.length()).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	t, _ := strconv.Atoi(sc.Text())
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for ; t > 0; t-- {
		sc.Scan()
		s := sc.Text()
		var e, o []byte
		// Same-parity digits keep their order; merge the two subsequences greedily.
		for i := 0; i < len(s); i++ {
			if (s[i]-'0')%2 == 1 {
				o = append(o, s[i])
			} else {
				e = append(e, s[i])
			}
		}
		i, j := 0, 0
		for i < len(e) && j < len(o) {
			if e[i] < o[j] {
				w.WriteByte(e[i])
				i++
			} else {
				w.WriteByte(o[j])
				j++
			}
		}
		w.Write(e[i:])
		w.Write(o[j:])
		w.WriteByte('\n')
	}
}
